import{_ as n,o as a,c as s,a1 as t}from"./chunks/framework.DYnGRJP5.js";const u=JSON.parse('{"title":"Setup & Deployment Guide","description":"","frontmatter":{},"headers":[],"relativePath":"doit-mern/setup-and-deployment.md","filePath":"doit-mern/setup-and-deployment.md"}'),i={name:"doit-mern/setup-and-deployment.md"};function o(l,e,r,p,d,h){return a(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="setup-deployment-guide" tabindex="-1">Setup &amp; Deployment Guide <a class="header-anchor" href="#setup-deployment-guide" aria-label="Permalink to &quot;Setup &amp; Deployment Guide&quot;">​</a></h1><p>This guide covers how to set up the MERN stack environment required for <strong>do.it</strong>, configure environment variables, and run both servers locally.</p><h2 id="_1-prerequisites" tabindex="-1">1. Prerequisites <a class="header-anchor" href="#_1-prerequisites" aria-label="Permalink to &quot;1. Prerequisites&quot;">​</a></h2><p>You need accounts and software for the following services:</p><ul><li><strong>MongoDB Atlas</strong> (Cloud Database)</li><li><strong>Google Cloud Console</strong> (OAuth 2.0 Client ID)</li><li><strong>Node.js</strong> (v18+ recommended)</li></ul><h2 id="_2-infrastructure-configuration" tabindex="-1">2. Infrastructure Configuration <a class="header-anchor" href="#_2-infrastructure-configuration" aria-label="Permalink to &quot;2. Infrastructure Configuration&quot;">​</a></h2><p>Because this app uses a custom Express backend, you must set up your database and OAuth credentials.</p><ol><li><strong>MongoDB Atlas</strong>: Go to <a href="https://www.mongodb.com/cloud/atlas" target="_blank" rel="noreferrer">MongoDB Atlas</a> and create a free cluster. Get your connection string.</li><li><strong>Google OAuth</strong>: Go to the <a href="https://console.cloud.google.com/" target="_blank" rel="noreferrer">Google Cloud Console</a>, create a project, and configure the OAuth consent screen. Create an <strong>OAuth client ID</strong> for a Web application. <ul><li>Add <code>http://localhost:5173</code> to the Authorized JavaScript origins.</li></ul></li><li><strong>JWT Secret</strong>: Generate a random secure string to use as your JWT secret key.</li></ol><hr><h2 id="_3-environment-variables" tabindex="-1">3. Environment Variables <a class="header-anchor" href="#_3-environment-variables" aria-label="Permalink to &quot;3. Environment Variables&quot;">​</a></h2><p>You need to create two separate <code>.env</code> files: one for the backend, and one for the frontend.</p><p><strong><code>backend/.env</code></strong></p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PORT=5001</span></span>
<span class="line"><span>MONGO_URI=your_mongodb_connection_string</span></span>
<span class="line"><span>JWT_SECRET=your_super_secret_jwt_key</span></span>
<span class="line"><span>GOOGLE_CLIENT_ID=your_google_oauth_client_id</span></span></code></pre></div><p><strong><code>frontend/.env</code></strong></p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>VITE_API_URL=http://localhost:5001/api</span></span>
<span class="line"><span>VITE_GOOGLE_CLIENT_ID=your_google_oauth_client_id</span></span></code></pre></div><hr><h2 id="_4-running-locally" tabindex="-1">4. Running Locally <a class="header-anchor" href="#_4-running-locally" aria-label="Permalink to &quot;4. Running Locally&quot;">​</a></h2><p>You will need to run both the frontend and backend servers simultaneously.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Clone the repository</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/yuvrajshrirame/doit-mern.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doit-mern</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Install Backend Dependencies &amp; Start Server</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server.js</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Runs on port 5001</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. Open a new terminal, Install Frontend Dependencies &amp; Start Server</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../frontend</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Runs on port 5173</span></span></code></pre></div><p>Access the app at <code>http://localhost:5173</code>.</p><hr><h2 id="_5-building-deployment" tabindex="-1">5. Building &amp; Deployment <a class="header-anchor" href="#_5-building-deployment" aria-label="Permalink to &quot;5. Building &amp; Deployment&quot;">​</a></h2><p><strong>do.it</strong> requires two separate deployments:</p><h3 id="backend-deployment-render-heroku-digitalocean" tabindex="-1">Backend Deployment (Render, Heroku, DigitalOcean) <a class="header-anchor" href="#backend-deployment-render-heroku-digitalocean" aria-label="Permalink to &quot;Backend Deployment (Render, Heroku, DigitalOcean)&quot;">​</a></h3><ol><li>Deploy the <code>backend</code> folder as a Node.js web service.</li><li>Add your <code>MONGO_URI</code>, <code>JWT_SECRET</code>, and <code>GOOGLE_CLIENT_ID</code> to the environment variables dashboard.</li></ol><h3 id="frontend-deployment-vercel-netlify" tabindex="-1">Frontend Deployment (Vercel, Netlify) <a class="header-anchor" href="#frontend-deployment-vercel-netlify" aria-label="Permalink to &quot;Frontend Deployment (Vercel, Netlify)&quot;">​</a></h3><ol><li>Deploy the <code>frontend</code> folder as a standard Vite React application.</li><li>Add your <code>VITE_API_URL</code> (pointing to your live backend URL) and <code>VITE_GOOGLE_CLIENT_ID</code> to the environment variables.</li><li>Don&#39;t forget to add your live frontend URL to your Google Cloud Console <strong>Authorized JavaScript origins</strong>!</li></ol>`,27)])])}const g=n(i,[["render",o]]);export{u as __pageData,g as default};
